/*
 * Consumes the ml/ (WS1) golden vectors for the int8 gallery matcher
 * (docs/INTERFACES.md 1), generated by `python -m sentinel_ml.golden`:
 *   gallery_v1.sgal, queries_f32.bin, queries_i8.bin, expected.csv,
 *   scores.csv, quant_vectors.csv, bad/<name>.sgal + bad/expected_errors.csv.
 * Directory comes from -DSN_GOLDEN_DIR (CMake cache var, default ml/golden).
 * Tolerances per MANIFEST.json: decisions exact, scores within 1e-5.
 */
#include "sn_test.h"
#include "sn_gallery.h"
#include <stdlib.h>

#ifndef SN_GOLDEN_DIR
#define SN_GOLDEN_DIR "../../ml/golden"
#endif

#define SCORE_TOL 1e-5
#define MAX_FILE  (SN_GAL_MAX_BLOB_SIZE + 64u)
#define N_QUERIES 64u

static uint8_t      g_blob[MAX_FILE];
static size_t       g_blob_len;
static sn_gallery_t G;
static int8_t       g_q8[N_QUERIES][SN_EMB_DIM];

static size_t read_file(const char *rel, uint8_t *buf, size_t cap)
{
    char path[512];
    FILE *f;
    size_t n;
    snprintf(path, sizeof(path), "%s/%s", SN_GOLDEN_DIR, rel);
    f = fopen(path, "rb");
    if (f == NULL) {
        printf("  cannot open %s\n", path);
        return 0u;
    }
    n = fread(buf, 1u, cap, f);
    fclose(f);
    return n;
}

static FILE *open_csv(const char *rel)
{
    char path[512];
    char header[256];
    FILE *f;
    snprintf(path, sizeof(path), "%s/%s", SN_GOLDEN_DIR, rel);
    f = fopen(path, "r");
    if ((f != NULL) && (fgets(header, sizeof(header), f) == NULL)) {
        fclose(f);
        f = NULL;
    }
    if (f == NULL) {
        printf("  cannot open %s\n", path);
    }
    return f;
}

static int load_gallery(void)
{
    g_blob_len = read_file("gallery_v1.sgal", g_blob, sizeof(g_blob));
    if (g_blob_len == 0u) {
        return 0;
    }
    return sn_gallery_parse(&G, g_blob, g_blob_len) == SN_GAL_OK;
}

static int load_queries(void)
{
    return read_file("queries_i8.bin", (uint8_t *)g_q8, sizeof(g_q8)) == sizeof(g_q8);
}

static void golden_gallery_blob(void)
{
    static const uint16_t ids[8] = { 1u, 2u, 3u, 4u, 7u, 9u, 12u, 13u };
    static const uint8_t protos[8] = { 5u, 3u, 20u, 1u, 4u, 4u, 2u, 2u };
    static const int16_t thr[8] = { 18022, 18022, 18022, 18022, 22938, 13107, 18022, 18022 };
    uint32_t i;
    CHECK(load_gallery());
    CHECK_EQ_INT(G.n_people, 8u);
    for (i = 0u; i < 8u; i++) {
        CHECK_EQ_INT(G.people[i].id, ids[i]);
        CHECK_EQ_INT(G.people[i].n_protos, protos[i]);
        CHECK_EQ_INT(G.people[i].threshold_q15, thr[i]);
    }
    CHECK_STR(G.people[0].name, "Ashton");
    CHECK_STR(G.people[4].name, "Strict-Sam");
    /* our writer reproduces the blob byte for byte */
    {
        static uint8_t out[MAX_FILE];
        sn_gal_person_spec_t specs[8];
        size_t len = 0u;
        for (i = 0u; i < 8u; i++) {
            specs[i].id = G.people[i].id;
            specs[i].n_protos = G.people[i].n_protos;
            specs[i].threshold_q15 = G.people[i].threshold_q15;
            specs[i].name = G.people[i].name;
            specs[i].protos = G.people[i].protos;
        }
        CHECK_EQ_INT(sn_gallery_write(out, sizeof(out), specs, 8u, &len), SN_GAL_OK);
        CHECK_EQ_INT(len, g_blob_len);
        CHECK(memcmp(out, g_blob, len) == 0);
    }
}

static void golden_quant_vectors(void)
{
    FILE *f = open_csv("quant_vectors.csv");
    char line[256];
    int rows = 0;
    CHECK(f != NULL);
    if (f == NULL) {
        return;
    }
    while (fgets(line, sizeof(line), f) != NULL) {
        unsigned int bits;
        int want;
        char xs[64];
        float in[SN_EMB_DIM];
        int8_t q[SN_EMB_DIM];
        if (sscanf(line, "%x,%63[^,],%d", &bits, xs, &want) != 3) {
            continue;
        }
        memset(in, 0, sizeof(in));
        memcpy(&in[0], &bits, sizeof(float));
        sn_embed_quantize(in, q);
        if (q[0] != want) {
            printf("  quant %08x (%s): got %d want %d\n", bits, xs, q[0], want);
        }
        CHECK_EQ_INT(q[0], want);
        rows++;
    }
    fclose(f);
    CHECK(rows >= 20);
}

static void golden_query_quantization(void)
{
    static float qf[N_QUERIES][SN_EMB_DIM];
    uint32_t i;
    int mism = 0;
    CHECK(load_queries());
    CHECK_EQ_INT(read_file("queries_f32.bin", (uint8_t *)qf, sizeof(qf)), sizeof(qf));
    for (i = 0u; i < N_QUERIES; i++) {
        int8_t q[SN_EMB_DIM];
        sn_embed_quantize(qf[i], q);
        if (memcmp(q, g_q8[i], SN_EMB_DIM) != 0) {
            mism++;
        }
    }
    CHECK_EQ_INT(mism, 0);
}

static void golden_expected_matches(void)
{
    FILE *f;
    char line[256];
    int rows = 0;
    CHECK(load_gallery());
    CHECK(load_queries());
    f = open_csv("expected.csv");
    CHECK(f != NULL);
    if (f == NULL) {
        return;
    }
    while (fgets(line, sizeof(line), f) != NULL) {
        unsigned idx;
        char kase[64];
        int match_id;
        int best_id;
        double best;
        double second;
        sn_match_t m;
        int got_best_id;
        if (sscanf(line, "%u,%63[^,],%d,%d,%lf,%lf", &idx, kase, &match_id, &best_id, &best,
                   &second) != 6) {
            continue;
        }
        if (idx >= N_QUERIES) {
            CHECK(0);
            continue;
        }
        sn_gallery_match(&G, g_q8[idx], &m);
        got_best_id = (m.best_idx < 0) ? -1 : (int)G.people[m.best_idx].id;
        if ((m.matched ? (int)m.id : -1) != match_id) {
            printf("  case %u %s: match %d want %d (best %.9f second %.9f)\n", idx, kase,
                   m.matched ? (int)m.id : -1, match_id, m.best_score, m.second_score);
        }
        CHECK_EQ_INT(m.matched ? (int)m.id : -1, match_id);
        CHECK_EQ_INT(got_best_id, best_id);
        CHECK_NEAR(m.best_score, best, SCORE_TOL);
        CHECK_NEAR(m.second_score, second, SCORE_TOL);
        rows++;
    }
    fclose(f);
    CHECK_EQ_INT(rows, (int)N_QUERIES);
}

static void golden_person_scores(void)
{
    FILE *f;
    char line[128];
    int rows = 0;
    CHECK(load_gallery());
    CHECK(load_queries());
    f = open_csv("scores.csv");
    CHECK(f != NULL);
    if (f == NULL) {
        return;
    }
    while (fgets(line, sizeof(line), f) != NULL) {
        unsigned idx;
        unsigned pid;
        double want;
        uint32_t i;
        const sn_gal_person_t *p = NULL;
        if (sscanf(line, "%u,%u,%lf", &idx, &pid, &want) != 3) {
            continue;
        }
        for (i = 0u; i < G.n_people; i++) {
            if (G.people[i].id == pid) {
                p = &G.people[i];
            }
        }
        CHECK(p != NULL);
        if ((p != NULL) && (idx < N_QUERIES)) {
            CHECK_NEAR(sn_gallery_person_score(p, g_q8[idx]), want, SCORE_TOL);
        }
        rows++;
    }
    fclose(f);
    CHECK_EQ_INT(rows, (int)(N_QUERIES * 8u));
}

static void golden_bad_blobs(void)
{
    FILE *f = open_csv("bad/expected_errors.csv");
    char line[256];
    int rows = 0;
    CHECK(f != NULL);
    if (f == NULL) {
        return;
    }
    while (fgets(line, sizeof(line), f) != NULL) {
        char file[128];
        char err[64];
        char rel[160];
        uint8_t *buf;
        size_t n;
        sn_gallery_t g;
        sn_gal_status_t st;
        if (sscanf(line, "%127[^,],%63s", file, err) != 2) {
            continue;
        }
        snprintf(rel, sizeof(rel), "bad/%s", file);
        buf = (uint8_t *)malloc(MAX_FILE);         /* exact-size reads: ASan sees overreads */
        n = read_file(rel, buf, MAX_FILE);
        {
            uint8_t *exact = (uint8_t *)malloc((n > 0u) ? n : 1u);
            memcpy(exact, buf, n);
            st = sn_gallery_parse(&g, exact, n);
            free(exact);
        }
        free(buf);
        if (strcmp(sn_gal_status_name(st), err) != 0) {
            printf("  %s: got %s want %s\n", file, sn_gal_status_name(st), err);
        }
        CHECK_STR(sn_gal_status_name(st), err);
        CHECK_EQ_INT(g.n_people, 0u);
        rows++;
    }
    fclose(f);
    CHECK(rows >= 10);
}

int main(int argc, char **argv)
{
    TEST_BEGIN(argc, argv);
    printf("golden dir: %s\n", SN_GOLDEN_DIR);
    RUN_TEST(golden_gallery_blob);
    RUN_TEST(golden_quant_vectors);
    RUN_TEST(golden_query_quantization);
    RUN_TEST(golden_expected_matches);
    RUN_TEST(golden_person_scores);
    RUN_TEST(golden_bad_blobs);
    TEST_END();
}
